Consider the following statements:

```sql
CREATE TABLE t0(c0 INT);
PRAGMA table_info('t0'); -- expected: {0|c0|INTEGER|false|NULL|false}, actual: {}
```
Unexpectedly, the `PRAGMA` provides no output. According to the documentation, it should be equivalent to the following, which actually provides an output:

```sql
SELECT * FROM pragma_table_info('t0'); -- {0|c0|INTEGER|false|NULL|false}
```
I found this issue based on commit bc9f086b9fcffb058763a6d1723da01127cd9100.

### What happens?

Using the C API, if I use a prepared statement (duckdb_prepare) to SELECT against a table, then proceed to try and add rows to that table via the appender, all the appender calls succeed, but the data isn't persisted to the table.

If instead I directly query the table (duckdb_query) the subsequent appender calls do persist the data to the table.


### To Reproduce

Removed error checking for brevity.

```

    instance_cache = duckdb_create_instance_cache();
    // Get a handle to an in-memory database
    duckdb_get_or_create_from_cache(instance_cache, NULL, &db, NULL, NULL);

    // Connect to the database
    duckdb_connect(db, &con);

    // drop any previous attempts
    duckdb_query(con, "drop table \"appendtest\"", NULL);

    // Create table with one column
    duckdb_query(con, "create table \"appendtest\" (\"Name\" VARCHAR(20))", &result);
    duckdb_destroy_result(&result);

    // If we use a prepared statement, then the subsequent append won't persist the value to the table
    if (use_prepared)
    {
        duckdb_prepare(con, "select Name from appendtest", &prepared_stmt);
        duckdb_execute_prepared_streaming(prepared_stmt, &result);

        // Note that even destroying the result and prepared statement doesn't help
        duckdb_destroy_result(&result);
        duckdb_destroy_prepare(&prepared_stmt);
    }
    // but if we use a direct query, then the append does persist the value
    else
    {
        duckdb_query(con, "select Name from appendtest", &result);
        duckdb_destroy_result(&result);
    }

    duckdb_appender_create(con, NULL, "appendtest", &appender);
    duckdb_append_varchar_length(appender, (const char *)"Bob", 3);
    duckdb_appender_end_row(appender);
    duckdb_appender_flush(appender);
    duckdb_appender_close(appender);
    duckdb_appender_destroy(&appender);

    // Now select from the table to see if the row is there
    duckdb_prepare(con, "select * from appendtest", &prepared_stmt);
    duckdb_execute_prepared_streaming(prepared_stmt, &result);
    is_streaming_result = duckdb_result_is_streaming(result);

    if (is_streaming_result)
    {
        // If this is a streaming result, use the correct fetch function
        chunk = duckdb_stream_fetch_chunk(result);
    }
    else
    {
        // Otherwise, just a normal fetch
        chunk = duckdb_fetch_chunk(result);
    }

    row_count = duckdb_data_chunk_get_size(chunk);
    printf("Fetched %lld rows\n", row_count);
```

