```ts
export enum ToastIcon {
    added = 'added',
    success = 'success',
    question = 'question',
    explanation = 'explanation',
}

interface ToastCustomOptions {
    timeout: number;
}

class ToastService {
    popToast(toastIcon: ToastIcon, body: string, customOptions?: ToastCustomOptions): void;
    popToast(
        toastIcon: ToastIcon,
        body: string,
        customOptions: ToastCustomOptions,
        actionButtonText: string,
    ): Promise<boolean>;
    popToast(
        toastIcon: ToastIcon,
        body: string,
        customOptions: ToastCustomOptions = { timeout: 3200 },
        actionButtonText?: string,
    ): Promise<boolean> | undefined {
        // Implementation
    }
}

const popToastParams: Parameters<ToastService['popToast']> = [ToastIcon.success, 'this is a toast'];
      ~~~~~~~~~~~~~~ <- Error!
```

### 🙁 Actual behavior

The assignment to `popToastParams` in line 30 fails with the error 2322 as following:
> Type `'[ToastIcon.success, string]'` is not assignable to type `'[toastIcon: ToastIcon, body: string, customOptions: ToastCustomOptions, actionButtonText: string]'`.
>   Source has 2 element(s) but target requires 4.(2322)

### 🙂 Expected behavior

I would expect `Parameters<ToastService['popToast']>` to evaluate to `[toastIcon: ToastIcon, body: string, customOptions?: ToastCustomOptions, actionButtonText?: string]`, since the `popToast` function's `customOptions` and `actionButtonText` are both optional.

